sp_widget.client_script:
function($window) {

    var c = this;

    c.stats = c.data.stats;

    c.openAddPatient = function() {

        // Future Add Patient Page

        $window.location.href =
        '?id=trackmed_add_patient';

    };

}

sp_widget.css:
.trackmed-patients-overview {
  background: #f0f4f8;
  font-family: "Segoe UI", sans-serif;
}

/* HEADER */

.page-header {
  background: linear-gradient(
    135deg,
    #0a2463 0%,
    #1a73e8 60%,
    #00b4d8 100%
  );

  padding: 28px 32px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;

  border-radius: 0 0 20px 20px;
  margin-bottom: 24px;

  box-shadow: 0 4px 20px rgba(26,115,232,.30);
}

.breadcrumb {
  color: rgba(255,255,255,.75);
  font-size: 13px;
  margin-bottom: 6px;
}

.breadcrumb a {
  color: #fff;
  text-decoration: none;
}

.breadcrumb a:hover {
  text-decoration: underline;
}

.sep {
  margin: 0 6px;
}

.page-title {
  color: white;
  font-size: 26px;
  font-weight: 700;
  margin: 0;
}

.page-title i {
  margin-right: 8px;
}

.page-subtitle {
  color: rgba(255,255,255,.8);
  margin-top: 8px;
}

.btn-primary-action {
  background: rgba(255,255,255,.15);
  border: 2px solid rgba(255,255,255,.35);
  color: white;

  padding: 12px 22px;
  border-radius: 10px;

  cursor: pointer;
  font-weight: 600;
}

.btn-primary-action:hover {
  background: rgba(255,255,255,.25);
}

/* STATS */

.patient-stats-row {
  display: grid;
  grid-template-columns: repeat(4,1fr);

  gap: 16px;
  padding: 0 28px 28px;
}

.mini-stat-card {
  background: white;

  border-radius: 14px;
  padding: 20px;

  display: flex;
  align-items: center;
  gap: 15px;

  box-shadow: 0 2px 12px rgba(0,0,0,.08);

  transition: .3s;
}

.mini-stat-card:hover {
  transform: translateY(-3px);
}

.mini-stat-icon {
  width: 48px;
  height: 48px;

  border-radius: 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 20px;
}

.blue-icon {
  background: #dbeafe;
  color: #1a73e8;
}

.green-icon {
  background: #dcfce7;
  color: #16a34a;
}

.orange-icon {
  background: #ffedd5;
  color: #ea580c;
}

.purple-icon {
  background: #ede9fe;
  color: #7c3aed;
}

.mini-stat-value {
  font-size: 26px;
  font-weight: 800;
  color: #1a2332;
}

.mini-stat-label {
  font-size: 13px;
  color: #64748b;
}

